def move_guest_photos(apps, schema_editor):
    """The one ID photo a guest could have before moves to their latest stay."""
    Guest, IdPhoto = apps.get_model("core", "Guest"), apps.get_model("core", "IdPhoto")
    for g in Guest.objects.exclude(id_photo_id=""):
        latest = g.stays.order_by("-check_in", "-pk").first()
        if latest:
            IdPhoto.objects.create(stay=latest, person=g.name, file_id=g.id_photo_id,
                                   name=f"{g.name}_{latest.pk}_{latest.check_in:%d-%m-%Y}.jpg")


